/// Texto no idioma do app; {0} é trocado pelo valor
func t(_ key: String, _ arg: String? = nil) -> String {
    let lang = L10n.current
    var s = L10n.T[lang]?[key] ?? L10n.T["en"]?[key] ?? key
    if let arg { s = s.replacingOccurrences(of: "{0}", with: arg) }
    return s
}
